def load_data():
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
                if isinstance(data, list) and len(data) > 0:
                    return data
                return ALL_INITIAL_DATA
        except Exception:
            return ALL_INITIAL_DATA
    else:
        save_data(ALL_INITIAL_DATA)
        return ALL_INITIAL_DATA

def save_data(data):
    try:
        with open(DATA_FILE, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def load_progress():
    if os.path.exists(PROGRESS_FILE):
        try:
            with open(PROGRESS_FILE, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return {}
    return {}

def save_progress(progress):
    try:
        with open(PROGRESS_FILE, "w", encoding="utf-8") as f:
            json.dump(progress, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

def download_gdrive_file(url):
    match = re.search(r"/d/([a-zA-Z0-9_-]+)", url) or re.search(r"id=([a-zA-Z0-9_-]+)", url)
    if not match:
        return None, "Google Drive-ის არასწორი ლინკი! დარწმუნდით, რომ ლინკი საჯაროა ('Anyone with the link')."
    file_id = match.group(1)
    download_url = f"https://drive.google.com/uc?export=download&id={file_id}"
    try:
        req = urllib.request.Request(download_url, headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req) as response:
            data = response.read()
        return data, None
    except Exception as e:
        return None, f"ჩამოტვირთვის შეცდომა: {str(e)}"

# ==============================================================================
# 2. ULTRA-ROBUST PARSER ENGINE
# ==============================================================================
def parse_raw_text(full_text, selected_code, file_name="uploaded_file"):
    full_text = full_text.replace("\r\n", "\n").replace("\r", "\n")
    
    if re.search(r"\n\s*[-=*]{3,}\s*\n", full_text):
        blocks = [b.strip() for b in re.split(r"\n?\s*[-=*]{3,}\s*\n?", full_text) if b.strip()]
    elif len([b for b in re.split(r"\n\s*\n+", full_text) if b.strip()]) > 1:
        blocks = [b.strip() for b in re.split(r"\n\s*\n+", full_text) if b.strip()]
    else:
        pattern = r"(?:^|\n)\s*(?=(?:კაზუსი|ტესტი|კითხვა|საქმე|ქეისი|№|#|N|\d+[\.\)\-–—])\s*)"
        blocks = [b.strip() for b in re.split(pattern, full_text, flags=re.IGNORECASE) if b.strip()]

    if not blocks:
        blocks = [full_text.strip()]

    new_cases = []
    for idx, block in enumerate(blocks):
        if not block or len(block) < 10:
            continue
        lines = [l.strip() for l in block.split("\n") if l.strip()]
        if not lines:
            continue

        title = lines[0][:80]
        options = []
        question_lines = []
        explanation_lines = []
        correct_idx = 0

        opt_pattern = r"^\s*([ა-დa-dA-D1-4])[\.\)]\s*(.*)"
        exp_keywords = ["დასაბუთება:", "განმარტება:", "იურიდიული დასაბუთება:", "სამართლებრივი დასაბუთება:", "სამართლებრივი საფუძველი:", "ანალიზი:"]
        correct_keywords = ["სწორი პასუხია:", "სწორი პასუხი:", "პასუხი:"]

        in_explanation = False

        for line in lines:
            is_correct_line = False
            for ck in correct_keywords:
                if ck in line.lower():
                    is_correct_line = True
                    l_low = line.lower()
                    if "ბ" in l_low or "b" in l_low or "2" in line:
                        correct_idx = 1
                    elif "გ" in l_low or "c" in l_low or "3" in line:
                        correct_idx = 2
                    elif "დ" in l_low or "d" in l_low or "4" in line:
                        correct_idx = 3
                    else:
                        correct_idx = 0
                    break

            if is_correct_line:
                continue

            if any(k in line.lower() for k in exp_keywords):
                in_explanation = True

            if in_explanation:
                explanation_lines.append(line)
            else:
                match = re.match(opt_pattern, line)
                if match:
                    options.append(line)
                else:
                    question_lines.append(line)

        question_text = "\n".join(question_lines) if question_lines else block
        explanation_text = "\n".join(explanation_lines) if explanation_lines else f"სამართლებრივი ანალიზი ეფუძნება ფაილს: {file_name}."

        if len(options) < 2:
            options = [
                "ა) სწორია / დასაშვებია (სამართლებრივი საფუძვლით)",
                "ბ) არასწორია / უსაფუძვლოა",
                "გ) ნაწილობრივ მართებულია",
                "დ) საჭიროებს დამატებით მტკიცებულებებს"
            ]

        new_cases.append({
            "id": f"upload_{int(time.time())}_{idx}",
            "title": f"{title}" if ("კაზუსი" in title or "ტესტი" in title or "მუხლი" in title) else f"კაზუსი #{idx+1}: {title}",
            "code": selected_code,
            "article": f"წყარო: {file_name}",
            "file_name": file_name,
            "question": question_text,
            "options": options,
            "correct_index": correct_idx,
            "explanation": explanation_text,
        })

    return new_cases

def parse_docx_or_text(uploaded_file, selected_code, file_name=None):
    if file_name is None:
        file_name = getattr(uploaded_file, "name", "gdrive_doc.docx")
    
    content_lines = []
    if file_name.endswith(".docx"):
        try:
            import docx
            doc = docx.Document(uploaded_file)
            for p in doc.paragraphs:
                p_text = p.text
                if p_text and p_text.strip():
                    content_lines.append(p_text.strip())
                else:
                    content_lines.append("")
            for table in doc.tables:
                for row in table.rows:
                    row_text = [cell.text.strip() for cell in row.cells if cell.text.strip()]
                    if row_text:
                        content_lines.append(" | ".join(row_text))
        except Exception:
            if hasattr(uploaded_file, "read"):
                content_lines = [str(uploaded_file.read().decode("utf-8", "ignore"))]
            else:
                content_lines = [str(uploaded_file)]
    else:
        if hasattr(uploaded_file, "read"):
            raw_text = str(uploaded_file.read().decode("utf-8", "ignore"))
        else:
            raw_text = str(uploaded_file)
        content_lines = raw_text.split("\n")

    full_text = "\n".join(content_lines)
    return parse_raw_text(full_text, selected_code, file_name)

